    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --surface: #151b2e;
        --surface-strong: #1d263d;
        --text: #f5f7fb;
        --muted: #c7d0e5;
        --accent: #9ad7ff;
        --accent-strong: #65c8ff;
        --border: #40506f;
        --shadow: #050713;
        --focus: #ffd166;
