        scroll-behavior: smooth;
      }

      body {
        min-width: 320px;
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.6;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #183252 0, transparent 32rem),
          radial-gradient(circle at bottom right, #37234e 0, transparent 30rem),
          var(--bg);
      }

