        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        padding: 0.75rem 1rem;
        color: #08111d;
        background: var(--focus);
        border-radius: 0.75rem;
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 0.2rem solid transparent;
      }

      header,
      main,
      footer {
        width: min(100% - 2rem, 58rem);
        margin-inline: auto;
      }

      header {
        padding: 5rem 0 2rem;
        text-align: center;
      }

      main {
        padding-bottom: 4rem;
      }

      footer {
        padding: 0 0 2rem;
        color: var(--muted);
        text-align: center;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent);
        font-size: 0.9rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2.25rem, 9vw, 5rem);
        line-height: 1;
        letter-spacing: -0.06em;
      }

      .intro {
        max-width: 42rem;
        margin: 1.25rem auto 0;
        color: var(--muted);
        font-size: clamp(1rem, 2.4vw, 1.2rem);
      }

      .faq-list {
        display: grid;
        gap: 1rem;
      }

      .example {
        overflow: clip;
        background: linear-gradient(145deg, var(--surface), var(--surface-strong));
        border: 1px solid var(--border);
        border-radius: 1.25rem;
        box-shadow: 0 1.25rem 3rem var(--shadow);
      }

      .question {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        width: 100%;
        padding: 1.25rem;
        color: var(--text);
        background: transparent;
        border: 0;
        font: inherit;
        font-size: 1.1rem;
        font-weight: 800;
